<?php

use Illuminate\Support\Facades\DB;use Modules\Cutting\Services\CuttingService;use Modules\Cutting\Services\LayExecutionService;use Modules\Inventory\Models\StockBalance;use Modules\MasterData\Models\Material;use Modules\MasterData\Models\ShadeGroup;use Modules\MasterData\Models\Uom;use Modules\MasterData\Services\UomConversionService;use Modules\Production\Services\MaterialIssueService;use Modules\Receiving\Models\FabricRoll;
it('mengonversi yard dan meter dengan faktor panjang standar',function(){$m=Uom::create(['company_id'=>1,'code'=>'MTR','name'=>'Meter']);$y=Uom::create(['company_id'=>1,'code'=>'YRD','name'=>'Yard']);$material=Material::create(['company_id'=>1,'code'=>'LEN-'.uniqid(),'name'=>'Length fabric','type'=>'FABRIC','tracking_level'=>'ROLL','buy_uom_id'=>$y->id,'use_uom_id'=>$m->id]);$svc=app(UomConversionService::class);expect($svc->convert(1,$material->id,1,$y->id,$m->id))->toBe(.9144)->and($svc->convert(1,$material->id,.9144,$m->id,$y->id))->toBe(1.0);});
it('BR-042 returns only Lay Roll dispatched leftover without double count',function(){[$user,$fabric,,$uom,,$warehouse,$mo,,,$colorway,$size]=shopFixture();$roll=FabricRoll::where('roll_no','R001')->firstOrFail();app(MaterialIssueService::class)->issue($mo,$warehouse->id,[['material_id'=>$fabric->id,'qty'=>200,'uom_id'=>$uom->id,'roll_id'=>$roll->id]],$user);$shade=ShadeGroup::create(['company_id'=>1,'code'=>'RET-'.uniqid(),'name'=>'Return']);$roll->update(['shade_group_id'=>$shade->id]);$cut=app(CuttingService::class)->create($mo->fresh(),[['colorway_id'=>$colorway->id,'size_id'=>$size->id,'qty_cut'=>100]],$user);$lays=app(LayExecutionService::class);$lay=$lays->createLay($cut,20,$user);$lays->addRoll($lay,$roll->fresh(),190,$user);$output=$lays->createOutput($lay->fresh(),$cut->lines->first()->id,100,$user);$lays->generateBundles($output,20,$user);$lays->completeLay($lay->fresh(),$user);$return=app(MaterialIssueService::class)->returnLeftover($mo->fresh(),$roll->fresh(),$warehouse->id,$user);$balance=StockBalance::withoutGlobalScopes()->where('material_id',$fabric->id)->where('warehouse_id',$warehouse->id)->where('roll_id',$roll->id)->firstOrFail();$dispatch=DB::table('fabric_dispatch_balances')->where('production_order_id',$mo->id)->where('roll_id',$roll->id)->first();expect((float)$return->qty_returned_use)->toBe(10.0)->and((float)$dispatch->qty_dispatched)->toBe(200.0)->and((float)$dispatch->qty_consumed)->toBe(190.0)->and((float)$dispatch->qty_returned)->toBe(10.0)->and((float)$balance->on_hand)->toBe(110.0);});
